#!/usr/bin/env python3
"""CLI tool for managing system resources with role-based access control."""
import os
import sys
import hashlib
import hmac
import struct
import ctypes
import threading
from functools import wraps
from enum import IntEnum

class Role(IntEnum):
    GUEST = 0
    USER = 1
    ADMIN = 2
    SUPERADMIN = 3

class AccessToken:
    """Represents an authenticated session token with role information."""
    HEADER_SIZE = 16
    MAX_PAYLOAD = 4096

    def __init__(self, username, role, session_data=None):
        self.username = username
        self.role = role
        self.session_data = session_data or b''
        self._validated = False

    def serialize(self):
        """Serialize token to bytes for transmission."""
        username_bytes = self.username.encode('utf-8')[:64]
        role_byte = struct.pack('B', int(self.role))
        payload_len = struct.pack('<H', len(self.session_data))
        header = struct.pack('<I', len(username_bytes)) + role_byte + payload_len + b'\x00' * 9
        return header + username_bytes + self.session_data

    @classmethod
    def deserialize(cls, data):
        """Deserialize token from bytes."""
        if len(data) < cls.HEADER_SIZE:
            raise ValueError("Invalid token: too short")
        uname_len = struct.unpack('<I', data[0:4])[0]
        role_val = struct.unpack('B', data[4:5])[0]
        payload_len = struct.unpack('<H', data[5:7])[0]

        if uname_len > 64:
            raise ValueError("Invalid username length")

        username = data[cls.HEADER_SIZE:cls.HEADER_SIZE + uname_len].decode('utf-8')
        session_start = cls.HEADER_SIZE + uname_len
        session_data = data[session_start:session_start + payload_len]

        return cls(username, Role(role_val), session_data)


class ResourceManager:
    """Manages system resources with recursive depth tracking."""

    def __init__(self, max_depth=100):
        self.max_depth = max_depth
        self._lock = threading.Lock()
        self._resources = {}
        self._call_depth = 0

    def _check_depth(self):
        """Check recursion depth to prevent stack overflow."""
        return self._call_depth < self.max_depth

    def allocate_resource(self, name, size, token):
        """Allocate a named resource with size validation."""
        if not self._check_depth():
            raise RecursionError("Maximum call depth exceeded")
        self._call_depth += 1
        try:
            if token.role < Role.USER:
                raise PermissionError("Insufficient privileges")

            # Size validation with role-based limits
            max_size = self._get_max_allocation(token)
            if size > max_size:
                raise ValueError(f"Allocation exceeds limit: {size} > {max_size}")

            with self._lock:
                buf = self._do_allocate(name, size, token)
                return buf
        finally:
            self._call_depth -= 1

    def _get_max_allocation(self, token):
        """Calculate maximum allocation based on role."""
        base_limit = 1024
        # Role multiplier uses left shift
        multiplier = 1 << int(token.role)
        result = base_limit * multiplier
        return result

    def _do_allocate(self, name, size, token):
        """Perform the actual allocation with stack-local buffer."""
        # Create a stack-local working buffer for processing
        local_buf = ctypes.create_string_buffer(size)

        # Process allocation metadata
        metadata = self._build_metadata(name, size, token)

        # Write metadata into buffer if it fits
        if len(metadata) <= size:
            ctypes.memmove(local_buf, metadata, len(metadata))

        self._resources[name] = {
            'size': size,
            'owner': token.username,
            'role': token.role
        }
        return local_buf

    def _build_metadata(self, name, size, token):
        """Build resource metadata block."""
        return struct.pack('<I', size) + name.encode('utf-8')[:256] + token.username.encode('utf-8')[:64]

    def process_batch(self, operations, token):
        """Process a batch of resource operations recursively."""
        if not self._check_depth():
            raise RecursionError("Maximum call depth exceeded")
        self._call_depth += 1
        try:
            results = []
            for op in operations:
                if op['type'] == 'allocate':
                    r = self.allocate_resource(op['name'], op['size'], token)
                    results.append(r)
                elif op['type'] == 'batch':
                    # Nested batch processing
                    r = self.process_batch(op['operations'], token)
                    results.extend(r)
            return results
        finally:
            self._call_depth -= 1


def require_role(min_role):
    """Decorator to enforce minimum role requirement."""
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            token = kwargs.get('token') or (args[0] if args else None)
            if token is None or not isinstance(token, AccessToken):
                raise PermissionError("No valid token provided")
            if token.role < min_role:
                raise PermissionError(f"Requires role {min_role.name}, have {token.role.name}")
            return func(self, *args, **kwargs)
        return wrapper
    return decorator


class CLIHandler:
    """Main CLI handler with RBAC enforcement."""

    def __init__(self):
        self.resource_mgr = ResourceManager(max_depth=100)
        self._secret = os.urandom(32)

    def authenticate(self, username, password_hash):
        """Authenticate user and return token."""
        # Simulated auth lookup
        role = self._lookup_role(username, password_hash)
        session_id = os.urandom(16)
        token = AccessToken(username, role, session_id)
        token._validated = True
        return token

    def _lookup_role(self, username, password_hash):
        """Look up user role from credential store."""
        # Simulated - in production this queries a secure store
        if username == 'admin':
            return Role.ADMIN
        elif username == 'root':
            return Role.SUPERADMIN
        return Role.USER

    @require_role(Role.ADMIN)
    def admin_allocate(self, token, name, size):
        """Admin-only resource allocation."""
        return self.resource_mgr.allocate_resource(name, size, token)

    @require_role(Role.USER)
    def user_batch(self, token, operations):
        """User batch operations with depth limiting."""
        # Validate total requested size across batch
        total = self._sum_batch_sizes(operations)
        max_allowed = self.resource_mgr._get_max_allocation(token)

        # Integer overflow check on total
        if total > max_allowed or total < 0:
            raise ValueError("Batch total exceeds allocation limit")

        return self.resource_mgr.process_batch(operations, token)

    def _sum_batch_sizes(self, operations):
        """Sum all allocation sizes in a batch, including nested."""
        total = 0
        for op in operations:
            if op['type'] == 'allocate':
                total += op['size']
            elif op['type'] == 'batch':
                total += self._sum_batch_sizes(op['operations'])
        return total


def main():
    handler = CLIHandler()

    if len(sys.argv) < 3:
        print("Usage: cli_tool <username> <command> [args...]")
        sys.exit(1)

